CREATE TABLE [sales].[SalesInvoices]([InvoiceId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SalesInvoices_Id] DEFAULT NEWSEQUENTIALID(),[InvoiceNumber] NVARCHAR(50) NOT NULL,[InvoiceDate] DATETIMEOFFSET NOT NULL,[CounterId] UNIQUEIDENTIFIER NULL,[ShiftId] UNIQUEIDENTIFIER NULL,[CustomerId] UNIQUEIDENTIFIER NULL,[WarehouseId] UNIQUEIDENTIFIER NOT NULL,[SalesPersonId] UNIQUEIDENTIFIER NULL,[Subtotal] DECIMAL(18,2) NOT NULL,[DiscountAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_Discount] DEFAULT 0,[TaxAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_Tax] DEFAULT 0,[RoundOff] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_Round] DEFAULT 0,[GrandTotal] DECIMAL(18,2) NOT NULL,[PaidAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_Paid] DEFAULT 0,[BalanceAmount] AS([GrandTotal]-[PaidAmount]) PERSISTED,[Status] NVARCHAR(20) NOT NULL,[Remarks] NVARCHAR(1000) NULL,[OriginalInvoiceId] UNIQUEIDENTIFIER NULL,[CreatedBy] NVARCHAR(256) NULL,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_SalesInvoices_Created] DEFAULT SYSUTCDATETIME(),[ModifiedOn] DATETIMEOFFSET NULL,[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_SalesInvoices] PRIMARY KEY([InvoiceId]),CONSTRAINT [UQ_SalesInvoices_Number] UNIQUE([InvoiceNumber]),CONSTRAINT [FK_SalesInvoices_Counter] FOREIGN KEY([CounterId]) REFERENCES [sales].[POSCounters]([CounterId]),CONSTRAINT [FK_SalesInvoices_Shift] FOREIGN KEY([ShiftId]) REFERENCES [sales].[POSShift]([ShiftId]),CONSTRAINT [FK_SalesInvoices_Customer] FOREIGN KEY([CustomerId]) REFERENCES [sales].[Customers]([CustomerId]),CONSTRAINT [FK_SalesInvoices_Warehouse] FOREIGN KEY([WarehouseId]) REFERENCES [inventory].[Warehouses]([WarehouseId]),CONSTRAINT [FK_SalesInvoices_Original] FOREIGN KEY([OriginalInvoiceId]) REFERENCES [sales].[SalesInvoices]([InvoiceId]),CONSTRAINT [CK_SalesInvoices_Status] CHECK([Status] IN('DRAFT','HELD','SUSPENDED','COMPLETED','CANCELLED','VOID','RETURNED','PARTIALLY_RETURNED')));
GO
CREATE INDEX [IX_SalesInvoices_Date] ON [sales].[SalesInvoices]([InvoiceDate] DESC,[Status],[WarehouseId]);
